#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <inttypes.h>

static long long llabs_ll(long long x) {
    return x < 0 ? -x : x;
}

static long long gcd_ll(long long a, long long b) {
    a = llabs_ll(a);
    b = llabs_ll(b);
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    errno = 0;
    long long a = strtoll(argv[1], &end1, 10);
    if (errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }
    if (*end1 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    errno = 0;
    long long b = strtoll(argv[2], &end2, 10);
    if (errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }
    if (*end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // range check: absolute value must not exceed 1,000,000
    if (llabs_ll(a) > 1000000LL || llabs_ll(b) > 1000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // special case both zero
    if (a == 0 && b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    // overflow check for negating LLONG_MIN (cannot take absolute value safely)
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    long long g = gcd_ll(a, b);
    // compute lcm = (|a| / g) * |b| with overflow detection
    long long abs_a = llabs_ll(a);
    long long abs_b = llabs_ll(b);
    __int128 lcm_tmp = (__int128)(abs_a / g) * (__int128)abs_b;
    if (lcm_tmp > LLONG_MAX) {
        puts("OVERFLOW");
        return 0;
    }
    long long l = (long long)lcm_tmp;
    printf("gcd=%lld lcm=%lld\n", g, l);
    return 0;
}
